let recordDetailView='records';const teamScheduleStates=new Map(),teamScheduleCache=new Map(),teamSchedulePending=new Map();
const currentScheduleMonth=()=>kstNow.getFullYear()*12+kstNow.getMonth();const scheduleMonthKey=n=>Math.floor(n/12)+'-'+pad(n%12+1);
function teamScheduleState(team){if(!teamScheduleStates.has(team))teamScheduleStates.set(team,{start:currentScheduleMonth(),end:currentScheduleMonth()+2,loading:false,errors:[],showPast:false});return teamScheduleStates.get(team);}
function teamScheduleSource(team){return ['hle','blg'].includes(team)?'lol':team==='ns'?'vlr':team;}
function teamScheduleRows(team){const state=teamScheduleState(team),source=teamScheduleSource(team),found=new Map();for(let m=state.start;m<=state.end;m++){const data=teamScheduleCache.get(source+'|'+scheduleMonthKey(m));for(const e of data?.events||[])if(e.team===team)found.set(e.id,e);}return [...found.values()].sort((a,b)=>(a.date+(a.time||'99:99')).localeCompare(b.date+(b.time||'99:99')));}
function selectRecordDetail(view){recordDetailView=view;$('team-record-detail').setAttribute('aria-pressed',String(view==='records'));$('team-schedule-detail').setAttribute('aria-pressed',String(view==='schedule'));renderRecords();if(view==='schedule')loadTeamSchedule(recordTeam);else loadRecords(recordTeam);}
$('team-record-detail').onclick=()=>selectRecordDetail('records');$('team-schedule-detail').onclick=()=>selectRecordDetail('schedule');
async function fetchTeamScheduleMonth(source,month,force){const key=source+'|'+month;if(teamSchedulePending.has(key))return teamSchedulePending.get(key);if(!teamScheduleCache.has(key)){try{const saved=JSON.parse(localStorage.getItem('matchday-team-schedule-'+key));if(Array.isArray(saved?.events))teamScheduleCache.set(key,saved);}catch{}}
 const saved=teamScheduleCache.get(key);if(!force&&saved&&Date.now()-(saved.loadedAt||0)<300000)return saved;
 const job=(async()=>{const r=await fetch('/api/schedule?source='+source+'&month='+month+(force?'&refresh=1':''),{signal:AbortSignal.timeout(60000)});const data=await r.json();if(!r.ok||!data.ok||!Array.isArray(data.events))throw Error('출처 연결 지연');const fresh={...data,loadedAt:Date.now()};teamScheduleCache.set(key,fresh);try{localStorage.setItem('matchday-team-schedule-'+key,JSON.stringify(fresh));}catch{}return fresh;})().finally(()=>teamSchedulePending.delete(key));teamSchedulePending.set(key,job);return job;}
async function loadTeamSchedule(team,force=false){const state=teamScheduleState(team);if(state.loading)return;state.loading=true;state.errors=[];const source=teamScheduleSource(team),months=[];for(let m=state.start;m<=state.end;m++)months.push(scheduleMonthKey(m));
 // Hydrate saved results before any request completes.
 months.forEach(month=>{const key=source+'|'+month;if(!teamScheduleCache.has(key)){try{const saved=JSON.parse(localStorage.getItem('matchday-team-schedule-'+key));if(Array.isArray(saved?.events))teamScheduleCache.set(key,saved);}catch{}}});
 const update=()=>{if(recordTeam===team&&recordDetailView==='schedule')renderTeamSchedule();};update();
 // Limit work to three simultaneous month requests.
 let cursor=0;await Promise.all(Array.from({length:Math.min(3,months.length)},async()=>{while(cursor<months.length){const month=months[cursor++];try{await fetchTeamScheduleMonth(source,month,force);}catch{state.errors.push(month);}update();}}));state.loading=false;update();}
function renderTeamSchedule(){const team=recordTeam,state=teamScheduleState(team),rows=teamScheduleRows(team),past=rows.filter(e=>e.date<today||e.status==='종료'),upcoming=rows.filter(e=>e.date>=today&&e.status!=='종료'),t=teamOf(team);const card=e=>`<article class="match-card${e.date===today?' agenda-today':''}"><div class="match-top"><span>${dayLabel(e.date)}${e.date===today?'<strong class="agenda-today-badge">오늘</strong>':''}</span><time>${e.time||'시간 미정'} KST · ${escapeHTML(e.status||'예정')}</time></div><div class="match-main">${e.participants?.length===2?'':sigil(t)}<h3 class="matchup">${matchup(e)}${e.score?`<strong class="score">${escapeHTML(e.score)}${matchResult(e)}</strong>`:''}</h3></div><p>${escapeHTML(e.venue)} · <a href="${escapeHTML(e.source||t.source)}" target="_blank" rel="noopener noreferrer">일정 출처</a></p></article>`;
 const at=rows.length?[...teamScheduleCache.values()].filter(r=>r.events?.some(e=>e.team===team)).map(r=>r.checkedAt).filter(Boolean).sort().at(0):null;
 $('records-status').classList.toggle('update-delayed',state.errors.length>0);$('records-status').textContent=state.loading?'일정 확인 중…':state.errors.length?'업데이트 지연 · 이전 확인 일정 유지':at?'마지막 확인 '+new Date(at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'일정 조회 완료';
 $('record-body').innerHTML=`<section class="team-schedule-panel"><h3>${t.name} 경기 일정</h3><p class="team-schedule-note">${scheduleMonthKey(state.start)} ~ ${scheduleMonthKey(state.end)} · 공개된 일정만 표시해요. 더 먼 일정도 아래에서 이어서 볼 수 있어요.</p>${upcoming.map(card).join('')||`<div class="team-schedule-empty">${state.loading?'경기 일정을 불러오는 중이에요.':state.errors.length?'일부 기간을 확인하지 못했어요. 다시 확인해 주세요.':'조회한 기간에 공개된 다음 경기가 없어요.'}</div>`}<div class="team-schedule-actions"><button id="team-more-future" ${state.loading?'disabled':''}>다음 3개월 더 보기</button><button id="team-more-past" ${state.loading?'disabled':''}>이전 3개월 불러오기</button><button id="team-refresh-schedule" ${state.loading?'disabled':''}>${state.errors.length?'다시 확인':'새로고침'}</button></div><details class="team-schedule-past" ${state.showPast?'open':''}><summary>지난 경기 ${past.length}개</summary>${past.slice().reverse().map(card).join('')||'<p class="team-schedule-note">이전 기간을 불러오면 과거 경기와 결과도 볼 수 있어요.</p>'}</details></section>`;
 $('team-more-future').onclick=()=>{state.end+=3;loadTeamSchedule(team);};$('team-more-past').onclick=()=>{state.start-=3;state.showPast=true;loadTeamSchedule(team);};$('team-refresh-schedule').onclick=()=>loadTeamSchedule(team,true);document.querySelector('.team-schedule-past').ontoggle=e=>{state.showPast=e.target.open;};
 document.querySelectorAll('#record-body .opponent-logo').forEach(img=>img.addEventListener('error',()=>img.style.display='none',{once:true}));}
